WITH resolved AS (
    SELECT c.id AS command_id, sp.id AS standard_path_id
    FROM tmp_mml_834_node_add_rows i
    JOIN public.mml_commands c
      ON c.command_code = i.command_code
     AND c.deprecated_at IS NULL
    JOIN public.standard_params sp
      ON sp.standard_path = i.standard_path
     AND sp.entry_type = 'parameter'
), deleted AS (
    DELETE FROM public.mml_command_sub_fields csf
    USING resolved r
    WHERE csf.command_id = r.command_id
      AND csf.standard_path_id = r.standard_path_id
    RETURNING csf.id
)
SELECT COUNT(*) AS deleted_rows FROM deleted;

COMMIT;
