    ('RMV VLAN_INTERFACE', 'Device.Ethernet.Interface.{i}.VlanInterface.{i}.VlanPppoeAddress.{i}.PppoeUser', 'PPPOE_USER', '{"zh-CN":"PPPOE_USER","en-US":"Pppoe User"}'::jsonb, true, false, 1742, 'WAN口配置参数管理', '删除 VLAN 子接口（RMV VLAN_INTERFACE）'),
    ('LST ETHERNET_IP_ROUTE', 'Device.Ethernet.IpRoute.{i}', 'IP_ROUTE', '{"zh-CN":"IP_ROUTE","en-US":"Ip Route"}'::jsonb, true, false, 1743, 'WAN口配置参数管理', '查询 静态路由表项（LST ETHERNET_IP_ROUTE）'),
    ('MOD ETHERNET_IP_ROUTE', 'Device.Ethernet.IpRoute.{i}', 'IP_ROUTE', '{"zh-CN":"IP_ROUTE","en-US":"Ip Route"}'::jsonb, true, false, 1744, 'WAN口配置参数管理', '修改 静态路由表项（MOD ETHERNET_IP_ROUTE）'),
    ('ADD ETHERNET_IP_ROUTE', 'Device.Ethernet.IpRoute.{i}', 'IP_ROUTE', '{"zh-CN":"IP_ROUTE","en-US":"Ip Route"}'::jsonb, true, false, 1745, 'WAN口配置参数管理', '添加 静态路由表项（ADD ETHERNET_IP_ROUTE）'),
    ('RMV ETHERNET_IP_ROUTE', 'Device.Ethernet.IpRoute.{i}', 'IP_ROUTE', '{"zh-CN":"IP_ROUTE","en-US":"Ip Route"}'::jsonb, true, false, 1746, 'WAN口配置参数管理', '删除 静态路由表项（RMV ETHERNET_IP_ROUTE）');


DO $$
DECLARE
    v_missing_commands text;
    v_missing_paths text;
    v_dup_final_code integer;
    v_existing_code_conflict text;
BEGIN
    SELECT string_agg(command_code || ' (' || rows || ' rows)', E'\n' ORDER BY command_code)
      INTO v_missing_commands
    FROM (
        SELECT i.command_code, COUNT(*) AS rows
        FROM tmp_mml_834_node_add_rows i
        LEFT JOIN public.mml_commands c
          ON c.command_code = i.command_code
         AND c.deprecated_at IS NULL
        WHERE c.id IS NULL
        GROUP BY i.command_code
    ) s;

    IF v_missing_commands IS NOT NULL THEN
        RAISE EXCEPTION 'missing mml_commands:%', E'\n' || v_missing_commands;
    END IF;

    SELECT string_agg(standard_path || ' (' || rows || ' rows)', E'\n' ORDER BY standard_path)
      INTO v_missing_paths
    FROM (
        SELECT i.standard_path, COUNT(*) AS rows
        FROM tmp_mml_834_node_add_rows i
        LEFT JOIN public.standard_params sp
          ON sp.standard_path = i.standard_path
         AND sp.entry_type = 'parameter'
        WHERE sp.id IS NULL
        GROUP BY i.standard_path
    ) s;

    IF v_missing_paths IS NOT NULL THEN
        RAISE EXCEPTION 'missing standard_params:%', E'\n' || v_missing_paths;
    END IF;

    WITH resolved AS (
        SELECT i.*, c.id AS command_id, sp.id AS standard_path_id
        FROM tmp_mml_834_node_add_rows i
        JOIN public.mml_commands c
          ON c.command_code = i.command_code
         AND c.deprecated_at IS NULL
        JOIN public.standard_params sp
          ON sp.standard_path = i.standard_path
         AND sp.entry_type = 'parameter'
    ), normalized AS (
        SELECT
            r.*,
            COALESCE(NULLIF(LEFT(r.base_mml_code, 100), ''), 'PATH_' || substr(md5(r.standard_path), 1, 8)) AS base_code
        FROM resolved r
    ), prepared AS (
        SELECT
            n.*,
            CASE
                WHEN COUNT(*) OVER (PARTITION BY n.command_id, n.base_code) > 1
                  OR EXISTS (
                      SELECT 1
                      FROM public.mml_command_sub_fields e
                      WHERE e.command_id = n.command_id
                        AND e.mml_code = n.base_code
                        AND e.standard_path_id <> n.standard_path_id
                  )
                THEN LEFT(n.base_code, 91) || '_' || substr(md5(n.standard_path), 1, 8)
                ELSE n.base_code
            END AS final_mml_code
        FROM normalized n
    )
    SELECT COUNT(*) - COUNT(DISTINCT (command_id, final_mml_code))
      INTO v_dup_final_code
    FROM prepared;

    IF v_dup_final_code <> 0 THEN
        RAISE EXCEPTION 'generated duplicate final mml_code count: %', v_dup_final_code;
    END IF;

    WITH resolved AS (
        SELECT i.*, c.id AS command_id, sp.id AS standard_path_id
        FROM tmp_mml_834_node_add_rows i
        JOIN public.mml_commands c
          ON c.command_code = i.command_code
         AND c.deprecated_at IS NULL
        JOIN public.standard_params sp
          ON sp.standard_path = i.standard_path
         AND sp.entry_type = 'parameter'
    ), normalized AS (
        SELECT
            r.*,
            COALESCE(NULLIF(LEFT(r.base_mml_code, 100), ''), 'PATH_' || substr(md5(r.standard_path), 1, 8)) AS base_code
        FROM resolved r
    ), prepared AS (
        SELECT
            n.*,
            CASE
                WHEN COUNT(*) OVER (PARTITION BY n.command_id, n.base_code) > 1
                  OR EXISTS (
                      SELECT 1
                      FROM public.mml_command_sub_fields e
                      WHERE e.command_id = n.command_id
                        AND e.mml_code = n.base_code
                        AND e.standard_path_id <> n.standard_path_id
                  )
                THEN LEFT(n.base_code, 91) || '_' || substr(md5(n.standard_path), 1, 8)
                ELSE n.base_code
            END AS final_mml_code
        FROM normalized n
    )
    SELECT string_agg(p.command_code || ' / ' || p.standard_path || ' -> ' || p.final_mml_code, E'\n' ORDER BY p.command_code, p.standard_path)
      INTO v_existing_code_conflict
    FROM prepared p
    JOIN public.mml_command_sub_fields e
      ON e.command_id = p.command_id
     AND e.mml_code = p.final_mml_code
     AND e.standard_path_id <> p.standard_path_id;

    IF v_existing_code_conflict IS NOT NULL THEN
        RAISE EXCEPTION 'final mml_code conflicts with existing rows:%', E'\n' || v_existing_code_conflict;
    END IF;
END $$;

WITH resolved AS (
    SELECT i.*, c.id AS command_id, sp.id AS standard_path_id, sp.access, sp.description
    FROM tmp_mml_834_node_add_rows i
    JOIN public.mml_commands c
      ON c.command_code = i.command_code
     AND c.deprecated_at IS NULL
    JOIN public.standard_params sp
      ON sp.standard_path = i.standard_path
     AND sp.entry_type = 'parameter'
), normalized AS (
    SELECT
        r.*,
        COALESCE(NULLIF(LEFT(r.base_mml_code, 100), ''), 'PATH_' || substr(md5(r.standard_path), 1, 8)) AS base_code,
        CASE WHEN r.access = 'READ_WRITE' THEN 'RW' ELSE 'RO' END::varchar(4) AS resolved_access_type,
        CASE
            WHEN NULLIF(r.description, '') IS NOT NULL THEN
                jsonb_build_object(
                    'zh-CN', r.description,
                    'en-US', COALESCE(NULLIF(r.label_i18n->>'en-US', ''), r.base_mml_code)
                )
            ELSE r.label_i18n
        END AS resolved_label_i18n,
        (r.access = 'READ_WRITE') AS resolved_is_required
    FROM resolved r
), prepared AS (
    SELECT
        n.*,
        CASE
            WHEN COUNT(*) OVER (PARTITION BY n.command_id, n.base_code) > 1
              OR EXISTS (
                  SELECT 1
                  FROM public.mml_command_sub_fields e
                  WHERE e.command_id = n.command_id
                    AND e.mml_code = n.base_code
                    AND e.standard_path_id <> n.standard_path_id
              )
            THEN LEFT(n.base_code, 91) || '_' || substr(md5(n.standard_path), 1, 8)
            ELSE n.base_code
        END AS final_mml_code
    FROM normalized n
), existing_max AS (
    SELECT command_id, COALESCE(MAX(sort_order), 0) AS max_sort_order
    FROM public.mml_command_sub_fields
    GROUP BY command_id
), ordered AS (
    SELECT
        p.*,
        COALESCE(em.max_sort_order, 0)
          + ROW_NUMBER() OVER (PARTITION BY p.command_id ORDER BY p.input_order, p.standard_path) AS new_sort_order
    FROM prepared p
    LEFT JOIN existing_max em ON em.command_id = p.command_id
), upserted AS (
    INSERT INTO public.mml_command_sub_fields (
        id, command_id, standard_path_id, mml_code, label_i18n,
        default_selected, is_required, sort_order, access_type, is_supported
    )
    SELECT
        gen_random_uuid(),
        o.command_id,
        o.standard_path_id,
        o.final_mml_code,
        o.resolved_label_i18n,
        true,
        o.resolved_is_required,
        o.new_sort_order,
        o.resolved_access_type,
        true
    FROM ordered o
    ON CONFLICT (command_id, standard_path_id) DO UPDATE
    SET mml_code         = EXCLUDED.mml_code,
        label_i18n       = EXCLUDED.label_i18n,
        default_selected = EXCLUDED.default_selected,
        is_required      = EXCLUDED.is_required,
        access_type      = EXCLUDED.access_type,
        is_supported     = true,
        deprecated_at    = NULL,
        updated_at       = NOW()
    RETURNING id
)
SELECT COUNT(*) AS upserted_rows FROM upserted;

COMMIT;
-- END former mml_add_834_paths_to_existing_command_nodes_20260704.sql

